// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 val1, uint256 val2, address actor) public {
        vm.assume(val1 != val2);
        vm.assume(actor != address(0));
        // set a baseline MinSum before initialization
        vm.prank(actor);
        c.SetMinSum(val1);
        // freeze the configuration
        vm.prank(actor);
        c.Initialized();
        // after initialization, SetMinSum must not change MinSum
        vm.prank(actor);
        c.SetMinSum(val2);
        assertEq(c.MinSum(), val1);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 initialVal, uint256 laterVal) public {
        vm.assume(initialVal != laterVal);
        initialVal = bound(initialVal, 0, type(uint256).max);
        laterVal = bound(laterVal, 0, type(uint256).max);

        c.SetMinSum(initialVal);
        c.Initialized();
        c.SetMinSum(laterVal);

        // Rule: after initialization, MinSum is immutable — it keeps the value
        // set before Initialized(), regardless of any later SetMinSum call.
        assertTrue(c.MinSum() == initialVal);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newLog) public {
        vm.assume(newLog != address(0));
        c.SetMinSum(1);
        c.SetLogFile(newLog);
        c.Initialized();
        bool ok;
        try c.SetLogFile(newLog) { ok = true; } catch { ok = false; }
        assertTrue(!ok && address(c.Log()) == newLog);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(uint256 amount) public {
        require(address(this).balance >= amount);
        uint256 before = c.balances(address(this));
        c.Deposit{value: amount}();
        uint256 afterB = c.balances(address(this));
        assert(afterB == before + amount);
    }
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest
{
